WITH flattened_attrs AS (SELECT id, ship_to, attributes, TRY_CAST(attributes['weight_kg'] AS DOUBLE) AS weight_kg, EXISTS(items, x -> x.price > 100) AS has_premium_item, COALESCE(attributes['device'], 'none') AS device_or_default, COALESCE(attributes['gift'], 'direct') AS gift_or_default, AGGREGATE(items, 0D, (acc, x) -> acc + x.qty * x.price, acc -> ROUND(acc, 2)) AS basket_amount FROM carts) SELECT CASE WHEN basket_amount >= 1800 THEN 'HIGH' ELSE 'LOW' END AS basket_amount_tier, CASE WHEN weight_kg >= 4.2 THEN 'HIGH' ELSE 'LOW' END AS weight_kg_tier, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) AS num_rows, PERCENTILE_APPROX(weight_kg, ARRAY(0.25, 0.5, 0.75)) AS weight_kg_quartiles, COUNT(DISTINCT device_or_default) AS distinct_device_or_defaults FROM flattened_attrs GROUP BY CASE WHEN basket_amount >= 1800 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN weight_kg >= 4.2 THEN 'HIGH' ELSE 'LOW' END HAVING COUNT(*) >= 1 ORDER BY distinct_device_or_defaults ASC
